// ComputerUser browser runtime shim.
// Lets skill/agent code use `await import("browser")` regardless of the install
// location, and always starting from Google Chrome unless another browser is
// requested explicitly.
//
// NOTE: `browser-client.mjs` is a real copy kept next to this file. The node_repl
// kernel only allows package modules to import files that live inside a
// configured node_modules root, so this file must NOT point at
// ../../browser/browser-client.mjs. install.ps1 refreshes the copy on every run.
import { setupBrowserRuntime } from "./browser-client.mjs";

export { setupBrowserRuntime };

export const DEFAULT_BROWSER = "chrome";

/** Reuse a single agent per node_repl session. */
export async function getAgent() {
  if (!globalThis.__computerUserAgent) {
    globalThis.__computerUserAgent = await setupBrowserRuntime({
      environment: "codex-app",
    });
  }
  return globalThis.__computerUserAgent;
}

/** List every connected browser instance. */
export async function listBrowsers() {
  const agent = await getAgent();
  return await agent.browsers.list();
}

/**
 * Resolve a connected browser by family ("chrome" | "brave" | "edge"), name or
 * instance id. Defaults to Google Chrome.
 */
export async function getBrowser(target = DEFAULT_BROWSER) {
  const agent = await getAgent();
  const browsers = await listBrowsers();
  if (browsers.length === 0) {
    throw new Error(
      "No browser is connected to the ComputerUser bridge. Open Chrome/Brave/Edge with the ComputerUser extension enabled and try again."
    );
  }
  const wanted = String(target).toLowerCase();
  const browser =
    browsers.find((b) => String(b.id) === String(target)) ??
    browsers.find((b) => String(b.family ?? "").toLowerCase() === wanted) ??
    browsers.find((b) => String(b.name ?? "").toLowerCase().includes(wanted));
  if (!browser) {
    const available = browsers
      .map((b) => `${b.family ?? "?"} (${b.name ?? b.id})`)
      .join(", ");
    throw new Error(
      `Browser "${target}" is not connected to the ComputerUser bridge. Connected: ${available}.`
    );
  }
  return await agent.browsers.get(browser.id);
}

export default { setupBrowserRuntime, getAgent, listBrowsers, getBrowser };
